// Entrada de la app: { id, q, max } (id = UUID anónimo de la instalación)
const body = $input.first().json.body || {};
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;
const id = String(body.id || '');
const q = String(body.q || '').trim().replace(/\s+/g, ' ').slice(0, 200);
const max = Math.max(1, Math.min(50, Math.round(Number(body.max) || 25)));
if (!UUID.test(id) || !q) return [{ json: { action: 'invalid' } }];

const LIMIT = 30;          // búsquedas al día por instalación
const CACHE_DAYS = 7;      // resultados guardados por texto
const CACHE_MAX = 3000;    // entradas como mucho
const data = $getWorkflowStaticData('global');
data.cache = data.cache || {};
data.counts = data.counts || {};
const now = Date.now();
const today = DateTime.now().setZone('Europe/Madrid').toISODate();

// limpieza: contadores de otros días y caché caducada
for (const d of Object.keys(data.counts)) if (d !== today) delete data.counts[d];
for (const [k, v] of Object.entries(data.cache)) if (!v || now - v.t > CACHE_DAYS * 864e5) delete data.cache[k];

const day = data.counts[today] = data.counts[today] || {};
const used = day[id] || 0;
if (used >= LIMIT) return [{ json: { action: 'limit', used } }];
day[id] = used + 1;

const key = q.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '') + '|' + max;
const hit = data.cache[key];
if (hit) return [{ json: { action: 'cache', items: hit.items, used: used + 1 } }];
return [{ json: { action: 'search', q, max, key, used: used + 1, cacheMax: CACHE_MAX } }];

// Mismos campos que usa la app: videoId, title, channel, thumb, duration (segundos), en el orden de la búsqueda
const iso = (s) => { const m = /P(?:(\d+)D)?T?(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?/.exec(s || ''); return m ? (+m[1] || 0) * 86400 + (+m[2] || 0) * 3600 + (+m[3] || 0) * 60 + (+m[4] || 0) : 0; };
const order = ($('YouTube · buscar').first().json.items || []).map(i => i.id && i.id.videoId).filter(Boolean);
const byId = Object.fromEntries(($input.first().json.items || []).map(v => [v.id, v]));
const items = order.filter(id => byId[id]).map(id => {
  const v = byId[id], sn = v.snippet || {}, th = sn.thumbnails || {};
  return { videoId: id, title: sn.title || id, channel: sn.channelTitle || '', thumb: (th.medium || th.default || {}).url || '', duration: iso(v.contentDetails && v.contentDetails.duration) };
});
const { key, cacheMax } = $('Límite y caché').first().json;
const data = $getWorkflowStaticData('global');
data.cache = data.cache || {};
data.cache[key] = { t: Date.now(), items };
const keys = Object.keys(data.cache);
if (keys.length > cacheMax) keys.sort((a, b) => data.cache[a].t - data.cache[b].t).slice(0, keys.length - cacheMax).forEach(k => delete data.cache[k]);
return [{ json: { items } }];
